  }
  function refreshBodyScrollLock() {
    document.body.style.overflow = hasOpenOverlay() ? 'hidden' : '';
  }
  window.__mtRefreshBodyScrollLock = refreshBodyScrollLock;
  function forceCloseGoodToKnowDrawer() {
    var root = document.getElementById('gtkDrawerRoot');
    if (!root) return;
    root.classList.remove('is-open', 'open');
    root.hidden = true;
    var backdrop = document.getElementById('gtkDrawerBackdrop');
    if (backdrop) backdrop.classList.remove('is-open', 'open');
    var openBtn = document.getElementById('gtkOpenBtn');
    if (openBtn) openBtn.setAttribute('aria-expanded', 'false');
    refreshBodyScrollLock();
  }
  document.addEventListener('click', function () {
    window.setTimeout(refreshBodyScrollLock, 0);
  }, true);
  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape') {
      forceCloseGoodToKnowDrawer();
      window.setTimeout(refreshBodyScrollLock, 0);
    }
  }, true);
  window.addEventListener('pageshow', refreshBodyScrollLock);
  window.addEventListener('load', refreshBodyScrollLock);
  var observer = new MutationObserver(function () {
    refreshBodyScrollLock();
  });
  observer.observe(document.body, { subtree: true, attributes: true, attributeFilter: ['class', 'hidden', 'style', 'aria-hidden'] });
})();

